def freeGreenDerivY (κ z y : ℝ) : ℝ :=
  if z < y then -(1 / 2) * Real.exp (-κ * (y - z))
  else if y < z then (1 / 2) * Real.exp (-κ * (z - y))
  else 0

def greenIterDerivY (κ : ℝ) (w : ℝ → ℝ) : ℕ → ℝ → ℝ → ℝ
  | 0, x, y => freeGreenDerivY κ x y
  | ℓ + 1, x, y => -∫ z : ℝ, greenIterKernel κ w ℓ x z * w z * freeGreenDerivY κ z y

def greenIterMixedDiag (κ : ℝ) (w : ℝ → ℝ) (ℓ : ℕ) (x : ℝ) : ℝ :=
  -∫ z : ℝ, greenIterDerivY κ w ℓ z x * w z * freeGreenDerivY κ z x

def diagGreenDeriv (κ : ℝ) (w : ℝ → ℝ) (x : ℝ) : ℝ :=
  ∑' m : ℕ, 2 * greenIterDerivY κ w (m + 1) x x

def greenKernelLeft (κ : ℝ) (w : ℝ → ℝ) (a x : ℝ) : ℝ :=
  (1 / (2 * κ)) * Real.exp (-κ * (a - x)) + ∑' m : ℕ, greenIterKernel κ w (m + 1) a x

def greenDerivLeft (κ : ℝ) (w : ℝ → ℝ) (a x : ℝ) : ℝ :=
  (1 / 2) * Real.exp (-κ * (a - x)) + ∑' m : ℕ, greenIterDerivY κ w (m + 1) a x

def greenKernelRight (κ : ℝ) (w : ℝ → ℝ) (a x : ℝ) : ℝ :=
  (1 / (2 * κ)) * Real.exp (-κ * (x - a)) + ∑' m : ℕ, greenIterKernel κ w (m + 1) a x

def greenDerivRight (κ : ℝ) (w : ℝ → ℝ) (a x : ℝ) : ℝ :=
  -(1 / 2) * Real.exp (-κ * (x - a)) + ∑' m : ℕ, greenIterDerivY κ w (m + 1) a x

def hm1NormSq (f : ℝ → ℝ) : ℝ :=
  ∫ ξ : ℝ, ‖fourierLine f ξ‖ ^ 2 / (4 + ξ ^ 2)

def recipGreenFluxInner (κ : ℝ) (w : ℝ → ℝ) (x : ℝ) : ℝ :=
  w x + (4 * κ ^ 5 / (κ ^ 2 - 1)) * (diagGreen κ w x - 1 / (2 * κ)) -
    (4 / (κ ^ 2 - 1)) * (diagGreen 1 w x - 1 / 2)

def regCutoff (δ' r : ℝ) : ℝ :=
  max 0 (min 1 (2 - r / δ'))

def regMovingFrameVec (κ : ℝ) (q : 𝓢(ℝ, ℝ)) : 𝓢(ℝ, ℝ) :=
  if h : ∃ g_tilde : 𝓢(ℝ, ℝ), ∀ x : ℝ, diagGreen κ q x = 1 / (2 * κ) + g_tilde x then
    (16 * κ ^ 5) • SchwartzMap.derivCLM ℝ ℝ (Classical.choose h)
  else 0

def regTruncatedVec (δ' κ : ℝ) (q : 𝓢(ℝ, ℝ)) : 𝓢(ℝ, ℝ) :=
  regCutoff δ' ‖ι q‖ • regMovingFrameVec κ q
